377: func (c *greenhouseContract) reviewAsync(env []string) <-chan greenhouseRun {
378: 	done := make(chan greenhouseRun, 1)
379: 	go func() {
380: 		output, err := c.posse(env, c.f.repo, c.reviewArgs()...)
381: 		done <- greenhouseRun{[]byte(output), err}
