386: func (c *greenhouseContract) finish(t *testing.T, done <-chan greenhouseRun) map[string]any {
387: 	t.Helper()
388: 	select {
389: 	case run := <-done:
390: 		if run.err != nil {
391: 			t.Fatalf("posse _greenhouse review: %v\n%s", run.err, run.output)
392: 		}
393: 		return decodeGreenhouseOutput(t, string(run.output))
394: 	case <-time.After(90 * time.Second):
395: 		t.Fatal("posse _greenhouse review did not return")
396: 		return nil
397: 	}
398: }
