560: 	request := map[string]any{"version": 2, "host": host, "run_id": current["run_id"], "input_id": current["input_id"], "gate_id": current["gate_id"], "expected": current["token"], "action_id": "contract-" + strconv.FormatInt(time.Now().UnixNano(), 10), "reason": "contract test"}
561: 	for key, value := range extra {
562: 		request[key] = value
563: 	}
