596: // buildGreenhouseProtocolOne builds the last real Greenhouse whose daemon
597: // speaks only protocol 1. Its module path predates the GitHub one, so the Go
598: // module proxy cannot serve it.
599: func buildGreenhouseProtocolOne(t *testing.T, f *workerTabsFixture) string {
600: 	t.Helper()
601: 	source := filepath.Join(f.root, "greenhouse-protocol-1")
602: 	binary := filepath.Join(f.root, "greenhouse-protocol-1-bin", "greenhouse")
603: 	for _, args := range [][]string{
604: 		{"init", "-q", source},
605: 		{"-C", source, "fetch", "-q", "--depth", "1", "https://github.com/Thanhbinh1905/greenhouse.git", greenhouseProtocolOneCommit},
606: 		{"-C", source, "checkout", "-q", "FETCH_HEAD"},
607: 	} {
608: 		if output, err := exec.Command("git", args...).CombinedOutput(); err != nil {
609: 			t.Fatalf("git %v: %v\n%s", args, err, output)
610: 		}
611: 	}
612: 	build := exec.Command("go", "build", "-o", binary, ".")
613: 	build.Dir = source
614: 	if output, err := build.CombinedOutput(); err != nil {
615: 		t.Fatalf("build protocol 1 Greenhouse: %v\n%s", err, output)
616: 	}
617: 	return binary
618: }
