	var modelKnown int
	err := db.QueryRowContext(ctx, `SELECT task_id,signal_id,verdict,report_sha256,targets_json,launch_number,profile_name,configured_model,model_known,created_at FROM review_verdicts WHERE task_id=?`, taskID).
