233: func greenhouseTaskMember(ctx context.Context, db *store.DB, project store.Project, task store.Task, repo string) (greenhouseMember, error) {
234: 	if !project.IsWorkspace() {
235: 		if repo != "" && repo != project.Name {
236: 			return greenhouseMember{}, axi.Usage("this Project has no Member " + repo)
237: 		}
238: 		return greenhouseMember{name: project.Name, root: project.Root, worktree: task.WorktreePath, targetBranch: taskTargetBranch(project, task)}, nil
239: 	}
240: 	if repo == "" {
241: 		return greenhouseMember{}, axi.Usage("a workspace Task needs --repo <member>")
242: 	}
243: 	projectRepos, err := db.ProjectRepos(ctx, project.ID)
244: 	if err != nil {
245: 		return greenhouseMember{}, err
246: 	}
247: 	taskRepos, err := db.TaskRepos(ctx, task.ID)
248: 	if err != nil {
249: 		return greenhouseMember{}, err
250: 	}
251: 	for _, taskRepo := range taskRepos {
252: 		if taskRepo.Repo != repo {
253: 			continue
254: 		}
255: 		for _, projectRepo := range projectRepos {
256: 			if projectRepo.Name == repo {
257: 				target := taskRepo.TargetBranch
258: 				if target == "" {
259: 					target = projectRepo.DefaultBranch
260: 				}
261: 				return greenhouseMember{name: repo, root: filepath.Join(project.Root, projectRepo.Path), worktree: taskRepo.WorktreePath, targetBranch: target}, nil
262: 			}
263: 		}
264: 	}
265: 	return greenhouseMember{}, axi.Usage("Task " + taskIDString(task.Seq) + " has no Member " + repo)
266: }
