296: 		env := setEnv(c.env, "PATH", filepath.Dir(protocolOne)+string(os.PathListSeparator)+testEnvValue(c.env, "PATH"))
297: 		before := len(c.verdicts(t))
298: 		c.authorCommit(t)
299: 		output, err := c.posse(env, f.repo, c.reviewArgs()...)
300: 		if err == nil || !strings.Contains(output, "greenhouse_protocol") || !strings.Contains(output, "speaks protocol 1 and Posse needs protocol 2") {
301: 			t.Fatalf("posse did not refuse a protocol 1 daemon naming both ranges: %v\n%s", err, output)
302: 		}
303: 		if got := len(c.verdicts(t)); got != before {
304: 			t.Fatalf("a refused daemon produced a Verdict")
305: 		}
306: 		state, err := os.ReadFile(filepath.Join(c.home, "state.json"))
307: 		if err != nil {
308: 			t.Fatal(err)
309: 		}
310: 		var runs struct {
311: 			Runs map[string]any `json:"runs"`
312: 		}
313: 		if err := json.Unmarshal(state, &runs); err != nil || len(runs.Runs) != 0 {
314: 			t.Fatalf("posse downgraded to protocol 1 and created runs: %v %s", err, state)
315: 		}
