365: 	output, err := c.posse(c.env, c.f.repo, c.reviewArgs()...)
366: 	if err != nil {
367: 		t.Fatalf("posse _greenhouse review: %v\n%s", err, output)
368: 	}
369: 	return decodeGreenhouseOutput(t, output)
