--- internal/greenhouse/protocol.go ---
1: // Package greenhouse is Posse's host adapter for Greenhouse review in host mode.
2: // It speaks AXI protocol version 2 to `greenhouse axi`, one request per
3: // invocation, against a daemon that Posse starts and places itself.
4: package greenhouse
5: 
6: import (
7: 	"bytes"
8: 	"context"
9: 	"encoding/json"
10: 	"errors"
11: 	"fmt"
12: 	"os/exec"
13: 	"strings"
14: )
15: 
16: // Protocol is the only AXI envelope version the adapter speaks. It never
17: // downgrades: host mode does not exist below version 2.
18: const Protocol = 2
19: 
20: // Range is an inclusive protocol version range.
21: type Range struct {
22: 	Min int `json:"min"`
23: 	Max int `json:"max"`
24: }
25: 
26: func (r Range) Includes(version int) bool { return r.Min <= version && version <= r.Max }
27: 
28: func (r Range) String() string {
29: 	if r.Min == r.Max {
30: 		return fmt.Sprint(r.Min)
31: 	}
32: 	return fmt.Sprintf("%d-%d", r.Min, r.Max)
33: }
34: 
35: // PosseRange is the protocol range this adapter accepts.
36: var PosseRange = Range{Min: Protocol, Max: Protocol}
37: 
38: // ProtocolError refuses a daemon whose range excludes the adapter's version.
39: type ProtocolError struct {
40: 	Daemon Range
41: }
42: 
43: func (e *ProtocolError) Error() string {
44: 	return fmt.Sprintf("the Greenhouse daemon speaks protocol %s and Posse needs protocol %s; Posse does not downgrade. Let its work settle, stop it and install a Greenhouse that speaks protocol %d", e.Daemon, PosseRange, Protocol)
45: }
46: 
47: // Host identifies the Posse host run, one per Task Member.
48: type Host struct {
49: 	Name string `json:"name"`
50: 	ID   string `json:"id"`
51: }
52: 
53: // Finding is one Greenhouse finding as host_result reports it.
54: type Finding struct {
55: 	ID          string `json:"id"`
56: 	Priority    string `json:"priority"`
57: 	Origin      string `json:"origin"`
58: 	File        string `json:"file"`
59: 	Start       int    `json:"start"`
60: 	End         int    `json:"end"`
61: 	Explanation string `json:"explanation"`
62: 	Action      string `json:"action"`
63: 	Rule        string `json:"rule"`
64: 	Head        string `json:"head"`
65: }
66: 
67: // HostResult is the exact-head review result of a host run.
68: type HostResult struct {
69: 	Grant        string    `json:"grant"`
70: 	ReviewID     string    `json:"review_id"`
71: 	Head         string    `json:"head"`
72: 	Target       string    `json:"target"`
73: 	ReviewBase   string    `json:"review_base"`
74: 	Status       string    `json:"status"`
75: 	Verdict      string    `json:"verdict"`
76: 	Current      bool      `json:"current"`
77: 	Findings     []Finding `json:"findings"`
78: 	RulesDigest  string    `json:"rules_digest"`
79: 	ConfigDigest string    `json:"config_digest"`
80: 	InputDigest  string    `json:"input_digest"`
81: 	Backend      string    `json:"backend"`
82: 	Model        string    `json:"model"`
83: 	Reason       string    `json:"reason"`
84: }
85: 
86: // Recovery is set while a run waits for recovery after an interruption.
87: type Recovery struct {
88: 	ID      string   `json:"id"`
89: 	Reason  string   `json:"reason"`
90: 	Options []string `json:"options"`
91: }
