172: func recordGreenhouseVerdict(ctx context.Context, db *store.DB, task store.Task, member greenhouseMember, roundDir, blockAt string, result greenhouse.RoundResult) (bool, store.Verdict, error) {
173: 	hr := result.Result
174: 	findings, err := json.MarshalIndent(hr.Findings, "", "  ")
175: 	if err != nil {
176: 		return false, store.Verdict{}, err
177: 	}
178: 	path := filepath.Join(roundDir, strings.ReplaceAll(result.Grant, "/", "_")+".findings.json")
179: 	if err := atomicfile.Write(path, findings, 0o600); err != nil {
180: 		return false, store.Verdict{}, err
181: 	}
182: 	digest := sha256.Sum256(findings)
183: 	verdict := store.Verdict{
184: 		TaskID: task.ID, Repository: member.name, Provider: store.GreenhouseReviewProvider, Protocol: strconv.Itoa(greenhouse.Protocol),
185: 		Grant: result.Grant, Head: hr.Head, Target: hr.Target, ReviewBase: hr.ReviewBase, Outcome: hr.Verdict,
186: 		RulesDigest: hr.RulesDigest, ConfigDigest: hr.ConfigDigest, InputDigest: hr.InputDigest, Backend: hr.Backend, Model: hr.Model,
187: 		FindingsHash: hex.EncodeToString(digest[:]), FindingsPath: path, Mode: "parallel",
188: 	}
189: 	if hr.Verdict == "findings" {
190: 		verdict.Blocking = greenhouseBlocking(hr.Findings, blockAt)
191: 	}
192: 	recorded, err := db.RecordGreenhouseVerdict(ctx, verdict, func(ctx context.Context) (string, error) {
193: 		return gitOutput(ctx, member.worktree, "rev-parse", "HEAD")
194: 	})
195: 	return recorded, verdict, err
196: }
